import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:farmgenie_fresh_cart/app.dart';
import 'package:farmgenie_fresh_cart/services/mock_session_controller.dart';

Future<void> openLogin(WidgetTester tester) async {
  await tester.pumpWidget(const FarmgenieApp());
  expect(find.byType(CircularProgressIndicator), findsOneWidget);
  await tester.pump(const Duration(milliseconds: 1500));
  await tester.pumpAndSettle();
}
Future<void> tapVisible(WidgetTester tester, Finder finder) async {
  await tester.ensureVisible(finder);
  await tester.pumpAndSettle();
  await tester.tap(finder);
  await tester.pumpAndSettle();
}
Future<void> login(WidgetTester tester, {bool remember = false}) async {
  await tester.enterText(find.byType(TextFormField).at(0), 'aarav');
  await tester.enterText(find.byType(TextFormField).at(1), 'demo');
  if (remember) await tapVisible(tester, find.byType(CheckboxListTile));
  await tapVisible(tester, find.text('Login'));
}
void main() {
  test('session validates, remembers only opted-in username, and resets', () {
    final session = MockSessionController();
    expect(session.login(username: ' ', password: 'x', rememberUsername: true), false);
    expect(session.login(username: 'a', password: ' ', rememberUsername: true), false);
    expect(session.login(username: ' aarav ', password: 'x', rememberUsername: true), true);
    session.logout();
    expect(session.isLoggedIn, false);
    expect(session.rememberedUsername, 'aarav');
    session.login(username: 'other', password: 'x', rememberUsername: false);
    session.logout();
    expect(session.rememberedUsername, isEmpty);
    session.dispose();
  });

  testWidgets('inline validation and password visibility', (tester) async {
    await openLogin(tester);
    await tapVisible(tester, find.text('Login'));
    expect(find.text('Enter your email or username.'), findsOneWidget);
    expect(find.text('Enter your password.'), findsOneWidget);
    await tester.enterText(find.byType(TextFormField).at(1), 'example');
    await tapVisible(tester, find.byTooltip('Show password'));
    expect(tester.widget<TextField>(find.byType(TextField).at(1)).obscureText, false);
    await tapVisible(tester, find.byTooltip('Hide password'));
    expect(tester.widget<TextField>(find.byType(TextField).at(1)).obscureText, true);
    await tester.pumpWidget(const SizedBox());
  });

  testWidgets('login, navigation, logout cancel and confirm, no authenticated back route', (tester) async {
    await openLogin(tester);
    await login(tester, remember: true);
    expect(find.text('Hello, Employee'), findsOneWidget);
    expect(find.text('Coming Soon'), findsNWidgets(5));
    await tapVisible(tester, find.text('Profile'));
    expect(find.text('Your profile'), findsOneWidget);
    await tapVisible(tester, find.text('Home'));
    expect(find.text('Hello, Employee'), findsOneWidget);
    await tapVisible(tester, find.byTooltip('Open profile'));
    await tapVisible(tester, find.text('Logout'));
    await tester.tap(find.text('Cancel'));
    await tester.pumpAndSettle();
    expect(find.text('Your profile'), findsOneWidget);
    await tapVisible(tester, find.text('Logout'));
    await tester.tap(find.widgetWithText(FilledButton, 'Logout'));
    await tester.pumpAndSettle();
    expect(find.text('Welcome Back'), findsOneWidget);
    expect(tester.widget<TextFormField>(find.byType(TextFormField).first).controller!.text, 'aarav');
    expect(tester.widget<TextFormField>(find.byType(TextFormField).last).controller!.text, isEmpty);
    await tester.binding.handlePopRoute();
    await tester.pumpAndSettle();
    expect(find.text('Your profile'), findsNothing);
    expect(find.text('Hello, Employee'), findsNothing);
    await tester.pumpWidget(const SizedBox());
  });

  for (final size in [const Size(320, 568), const Size(412, 915), const Size(800, 1000)]) {
    testWidgets('responsive layout at $size with large text and keyboard', (tester) async {
      tester.view.physicalSize = size;
      tester.view.devicePixelRatio = 1;
      tester.platformDispatcher.textScaleFactorTestValue = 2;
      addTearDown(() {
        tester.view.resetPhysicalSize();
        tester.view.resetDevicePixelRatio();
        tester.view.resetViewInsets();
        tester.platformDispatcher.clearTextScaleFactorTestValue();
      });
      await openLogin(tester);
      expect(tester.takeException(), isNull);
      tester.view.viewInsets = const FakeViewPadding(bottom: 240);
      await tester.pumpAndSettle();
      await login(tester);
      tester.view.resetViewInsets();
      await tester.pumpAndSettle();
      expect(tester.takeException(), isNull);
      await tapVisible(tester, find.text('Profile'));
      await tapVisible(tester, find.text('Logout'));
      expect(tester.takeException(), isNull);
      await tester.tap(find.text('Cancel'));
      await tester.pumpAndSettle();
      expect(find.text('Your profile'), findsOneWidget);
      await tester.pumpWidget(const SizedBox());
    });
  }
}
